/* eslint-disable */
/* global WebImporter */

/**
 * accordion-photo (homepage #brandvoice).
 * Rows:
 * - first row (one cell): the eyebrow "Our game changing principles", shown by the block as the
 *   lime pill inside the panel, above the items.
 * - then one row per item: [principle title | backdrop photo + description paragraph].
 * - Titles are the non-numeric headings of the items (the 01.-04. numerals are generated by the block).
 * - Backdrop photos: the source stacks the full-bleed images with the last one on top and fades the
 *   top layers out as the items advance, so item 1 shows the LAST image in document order
 *   (verified on the live page: 01 Openness = WvGO8 city aerial, 02 = vmfHf trophy, 03 = vl46
 *   crowd, 04 = LIi3). Known principles use the captured pairs; others pair in reverse order.
 * - Only the active item's description is in the DOM; the others fall back to the
 *   descriptions captured from the live page.
 */
const CAPTURED = {
  openness: {
    img: 'https://framerusercontent.com/images/WvGO8xUMy4lLara6y8XFtr78k.png',
    text: 'We embrace innovation and opportunity, shaping the future of tennis with curiosity and bold thinking.',
  },
  'breakthrough thinking': {
    img: 'https://framerusercontent.com/images/vmfHf59UpPpdnmQQcQu4ODzk97k.jpg',
    text: 'We challenge the status quo, pursuing game-changing ideas that elevate the sport and inspire the world.',
  },
  connection: {
    img: 'https://framerusercontent.com/images/vl46iR28aH0UflfUentyiAkkyTA.jpg',
    text: 'We bring tennis to the people: creating moments, stories, and innovations that ignite passion and unite fans.',
  },
  passion: {
    img: 'https://framerusercontent.com/images/LIi3IVS9qicXLenNIDQe3RLgj3k.png',
    text: 'We embody the Australian spirit: fearless, determined, and driven by an unwavering love for the game.',
  },
};
const CAPTURED_ORDER = ['Openness', 'Breakthrough thinking', 'Connection', 'Passion'];

function textOf(el) {
  const clone = el.cloneNode(true);
  clone.querySelectorAll('br').forEach((br) => br.replaceWith(' '));
  return clone.textContent.replace(/\s+/g, ' ').trim();
}

function imgSrc(img) {
  const src = img.getAttribute('src') || '';
  return /framerusercontent\.com\/images\//.test(src) ? src.split('?')[0] : src;
}

const isNumeral = (t) => /^\d+\.?$/.test(t);

export default function parse(element, { document }) {
  // eyebrow: a short paragraph that is not inside an item
  const titleEls = [...element.querySelectorAll('h1, h2, h3, h4, h5, h6')]
    .filter((h) => textOf(h) && !isNumeral(textOf(h)));
  // dedupe identical titles (breakpoint copies when cleanup did not run)
  const seen = new Set();
  const uniqueTitles = titleEls.filter((h) => {
    const k = textOf(h).toLowerCase();
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
  // when the known principles are present, any other heading is the eyebrow, not an item
  const known = uniqueTitles.filter((h) => CAPTURED[textOf(h).toLowerCase()]);
  const titles = known.length ? known : uniqueTitles;
  const headingEyebrow = known.length ? uniqueTitles.find((h) => !known.includes(h)) : null;

  // item container: climb from the title while the parent holds only this title
  const items = titles.map((h) => {
    let node = h;
    while (node.parentElement && node.parentElement !== element) {
      const count = [...node.parentElement.querySelectorAll('h1, h2, h3, h4, h5, h6')]
        .filter((x) => textOf(x) && !isNumeral(textOf(x))).length;
      if (count > 1) break;
      node = node.parentElement;
    }
    return { title: textOf(h), container: node };
  });

  const eyebrow = headingEyebrow || [...element.querySelectorAll('p')]
    .find((p) => textOf(p) && !items.some((it) => it.container.contains(p)));

  // backdrop photos: images that are not inside any item, in document order
  const photos = [...element.querySelectorAll('img')]
    .filter((img) => !(img.getAttribute('src') || '').startsWith('data:'))
    .filter((img) => !items.some((it) => it.container.contains(img)));
  const uniquePhotos = [];
  photos.forEach((img) => { if (!uniquePhotos.some((u) => imgSrc(u) === imgSrc(img))) uniquePhotos.push(img); });

  const list = items.length ? items : CAPTURED_ORDER.map((t) => ({ title: t, container: null }));
  // stacked layers: the top (last) image belongs to item 1
  const stack = uniquePhotos.slice().reverse();
  const usePhotos = stack.length === list.length;

  const cells = [];
  if (eyebrow) {
    const t = textOf(eyebrow);
    cells.push([t.charAt(0).toUpperCase() + t.slice(1)]);
  }
  list.forEach((item, i) => {
    const captured = CAPTURED[item.title.toLowerCase()] || {};
    const content = [];
    const capturedPhoto = captured.img && uniquePhotos.find((u) => imgSrc(u) === captured.img);
    let photo = null;
    if (capturedPhoto) photo = capturedPhoto;
    else if (usePhotos) photo = stack[i];
    const src = photo ? imgSrc(photo) : captured.img;
    if (src) {
      const img = document.createElement('img');
      img.src = src;
      img.alt = (photo && photo.getAttribute('alt')) || '';
      content.push(img);
    }
    const domDesc = item.container
      ? [...item.container.querySelectorAll('p')].find((p) => textOf(p) && textOf(p) !== item.title)
      : null;
    const descText = domDesc ? textOf(domDesc) : captured.text;
    if (descText) {
      const p = document.createElement('p');
      p.textContent = descText;
      content.push(p);
    }
    cells.push([item.title, content]);
  });

  const block = WebImporter.Blocks.createBlock(document, { name: 'accordion-photo', cells });
  element.replaceWith(block);
}
